  <style>
    :root {
      /* 9 tokens canônicos do Unooria Design System (Wireframe Cinza) */
      --superficie-base: #FFFFFF;
      --superficie-elevada: #FAFAFA;
      --superficie-midia: #E0E0E0;
      --borda-padrao: #C7C7C7;
      --borda-foco: #1A1A1A;
      --texto-primario: #1A1A1A;
      --texto-secundario: #6B6B6B;
      --acao-primaria: #1A1A1A;
      --acao-secundaria: #EDEDED;

      /* Tokens da casca de revisão externa (ferramenta de inspeção da esteira) */
      --casca-fundo: #0E131A;
      --casca-painel: #161D26;
      --casca-borda: #273344;
      --casca-texto-forte: #F0F4F8;
      --casca-texto-suave: #98A7BC;
      --casca-acento: #3874CB;
      --casca-acento-hover: #4B88E3;
