      flex-direction: column;
      overflow: hidden;
      min-width: 0;
    }

    /* BARRA SUPERIOR DA CASCA */
    header.casca-topo {
      height: 52px;
      background: var(--casca-painel);
      border-bottom: 1px solid var(--casca-borda);
      display: flex;
      align-items: center;
      justify-content: space-between;
