    .marca-pico { background: var(--casca-pico); color: #FFF; }
    .marca-aha { background: var(--casca-aha); color: #FFF; }
    .marca-trava { background: var(--casca-alerta); color: #FFF; }
    .marca-mem { background: #B38600; color: #FFF; }

    .topo-nav {
