    /* MOLDURA DESKTOP 1366x768 ESCALADA (com border de 8px em borda-padrao) */
    .moldura-desktop {
      width: 820px;
      height: 520px;
      background: var(--superficie-base);
      border: 8px solid var(--borda-padrao);
      border-radius: 12px;
      position: relative;
      overflow: hidden;
      box-shadow: 0 16px 36px rgba(0,0,0,0.5);
