    }

    /* COLUNA 3: PAINEL DA ETAPA */
    aside.casca-painel-etapa {
      background: var(--casca-painel);
      border-left: 1px solid var(--casca-borda);
      padding: 16px;
      overflow-y: auto;
      overflow-x: hidden;
      display: flex;
      flex-direction: column;
      gap: 16px;
