    }

    .painel-descricao-etapa {
      font-size: 14px;
      color: var(--casca-texto-suave);
      line-height: 1.55;
      word-break: break-word;
    }

    .painel-card-info {
      background: rgba(255, 255, 255, 0.04);
      border: 1px solid var(--casca-borda);
