      font-style: italic;
    }

    /* RODAPÉ DA CASCA DE REVISÃO */
    footer.casca-rodape {
      height: 48px;
      background: var(--casca-painel);
      border-top: 1px solid var(--casca-borda);
      display: flex;
      align-items: center;
