      padding: 0 16px;
      font-size: 12px;
      flex-shrink: 0;
      min-width: 0;
      gap: 16px;
      overflow: hidden;
    }

    .rodape-campo {
      display: flex;
      align-items: center;
      gap: 6px;
      min-width: 0;
      overflow: hidden;
      white-space: nowrap;
      text-overflow: ellipsis;
    }

    .rodape-rotulo {
      color: var(--casca-texto-suave);
      font-weight: 600;
      font-size: 11px;
      text-transform: uppercase;
      flex-shrink: 0;
    }

    .rodape-valor {
      color: var(--casca-texto-forte);
      font-family: monospace;
      font-weight: 600;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    /* =========================================================
       ESTILOS INTERNOS DOS QUADROS (LO-FI 9 TOKENS ESTRITOS)
       NADA DE CORES FORA DOS 9 TOKENS DENTRO DOS QUADROS
       ========================================================= */

    .quadro-tela {
      width: 100%;
      height: 100%;
      flex-direction: column;
      background: var(--superficie-base);
      color: var(--texto-primario);
