      bottom: 4px;
      right: 6px;
      font-size: 11px;
      color: var(--texto-secundario);
      background: rgba(255,255,255,0.92);
      padding: 2px 6px;
      border-radius: 3px;
      pointer-events: none;
      z-index: 99;
      font-family: monospace;
      border: 1px solid var(--borda-padrao);
    }

    /* TOPBARS DOS APPS SIMULADOS */
    .uai-topbar {
      height: 44px;
      border-bottom: 1px solid var(--borda-padrao);
