      align-items: center;
      justify-content: space-between;
      padding: 0 12px;
      background: var(--superficie-elevada);
      flex-shrink: 0;
    }

    .uai-topbar-titulo {
      font-size: 13px;
      font-weight: 700;
      color: var(--texto-primario);
    }

    .uai-topbar-menu {
      width: 28px;
      height: 28px;
      border: 1px solid var(--borda-padrao);
      border-radius: 4px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 12px;
      background: var(--superficie-base);
    }

    .unv-topbar {
      height: 44px;
      border-bottom: 1px solid var(--borda-padrao);
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 12px;
      background: var(--superficie-base);
      flex-shrink: 0;
    }

    .unv-topbar-logo {
      font-size: 15px;
      font-weight: 800;
      letter-spacing: -0.5px;
    }

    .unv-topbar-acoes {
      display: flex;
      gap: 10px;
      align-items: center;
      font-size: 12px;
    }

    .unv-tabbar {
      height: 48px;
      border-top: 1px solid var(--borda-padrao);
      display: flex;
      align-items: center;
      justify-content: space-around;
      background: var(--superficie-base);
      flex-shrink: 0;
      margin-top: auto;
    }

    .unv-tab-item {
      font-size: 11px;
      font-weight: 600;
      color: var(--texto-secundario);
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 2px;
    }

    .unv-tab-item.ativo {
      color: var(--texto-primario);
    }

    /* OVERLAY FIXO DE CTA DO GRÊMIO (Pedido 2 e 3 do PO) */
    .unv-mission-overlay {
      background: var(--superficie-elevada);
      border-bottom: 2px solid var(--borda-foco);
      padding: 8px 10px;
      font-size: 11px;
      line-height: 1.35;
      color: var(--texto-primario);
      flex-shrink: 0;
      max-height: 90px;
      overflow-y: auto;
    }

    .unv-mission-overlay strong {
      display: block;
      margin-bottom: 2px;
      text-transform: uppercase;
      font-size: 10px;
      letter-spacing: 0.5px;
    }

    /* ELEMENTOS BÁSICOS LO-FI */
    .btn-lofi {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 6px;
      padding: 10px 14px;
      border-radius: 6px;
      font-size: 13px;
      font-weight: 600;
      cursor: pointer;
      text-decoration: none;
      transition: all 0.15s;
      border: 1px solid transparent;
      min-height: 40px;
      text-align: center;
    }

    .btn-lofi-primario {
      background: var(--acao-primaria);
      color: var(--superficie-base);
    }

    .btn-lofi-secundario {
      background: var(--acao-secundaria);
      color: var(--texto-primario);
      border-color: var(--borda-padrao);
    }

    .btn-lofi-desabilitado {
      background: var(--acao-secundaria);
      color: var(--texto-secundario);
      cursor: not-allowed;
      border-color: var(--borda-padrao);
    }

    .card-lofi {
      background: var(--superficie-elevada);
      border: 1px solid var(--borda-padrao);
      border-radius: 8px;
      padding: 12px;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .marcador-midia {
      background: var(--superficie-midia);
      border: 1px solid var(--borda-padrao);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      color: var(--texto-secundario);
      font-size: 11px;
      position: relative;
      overflow: hidden;
    }

    .marcador-midia::before, .marcador-midia::after {
      content: "";
      position: absolute;
      top: 0; left: 0; right: 0; bottom: 0;
      background: linear-gradient(to top right, transparent calc(50% - 1px), var(--borda-padrao) calc(50% - 1px), var(--borda-padrao) calc(50% + 1px), transparent calc(50% + 1px));
      pointer-events: none;
    }

    .marcador-midia::after {
      background: linear-gradient(to top left, transparent calc(50% - 1px), var(--borda-padrao) calc(50% - 1px), var(--borda-padrao) calc(50% + 1px), transparent calc(50% + 1px));
    }

    .marcador-legenda {
      z-index: 2;
      background: var(--superficie-elevada);
      padding: 3px 8px;
      border-radius: 3px;
      border: 1px solid var(--borda-padrao);
      font-size: 11px;
      text-align: center;
      max-width: 90%;
    }

    /* CHAT UNOORIAAI */
    .chat-conversa {
      flex: 1;
      padding: 12px;
      display: flex;
      flex-direction: column;
      gap: 12px;
      overflow-y: auto;
    }

    .balao-chat {
      max-width: 86%;
      padding: 10px 12px;
      border-radius: 10px;
      font-size: 13px;
      line-height: 1.4;
    }

    .balao-usuario {
      align-self: flex-end;
      background: var(--superficie-midia);
      color: var(--texto-primario);
      border-bottom-right-radius: 2px;
    }

    .balao-ia {
      align-self: flex-start;
      background: var(--superficie-elevada);
      border: 1px solid var(--borda-padrao);
      color: var(--texto-primario);
      border-bottom-left-radius: 2px;
    }

    .pilulas-prompt {
      display: flex;
      flex-direction: column;
      gap: 6px;
      margin-top: 6px;
    }

    .pilula-item {
      background: var(--superficie-base);
      border: 1px solid var(--borda-padrao);
      padding: 8px 10px;
      border-radius: 16px;
      font-size: 12px;
      color: var(--texto-primario);
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: 6px;
      transition: background 0.15s;
    }

    .pilula-item:hover {
      background: var(--acao-secundaria);
    }

    .chat-input-area {
      padding: 10px;
      border-top: 1px solid var(--borda-padrao);
      background: var(--superficie-elevada);
      display: flex;
      gap: 8px;
      align-items: center;
    }

    .chat-campo {
      flex: 1;
      height: 38px;
      border: 1px solid var(--borda-padrao);
      border-radius: 20px;
      padding: 0 14px;
      font-size: 13px;
      background: var(--superficie-base);
      color: var(--texto-primario);
    }

    /* FEED E POSTCARD UNOOVISTA */
    .feed-scroll {
      flex: 1;
      overflow-y: auto;
      display: flex;
      flex-direction: column;
      gap: 12px;
      padding: 12px;
    }

    .postcard-lofi {
      border: 1px solid var(--borda-padrao);
      border-radius: 8px;
      background: var(--superficie-base);
      overflow: hidden;
      display: flex;
      flex-direction: column;
      gap: 8px;
      padding: 10px;
    }

    .postcard-cabecalho {
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .perfil-avatar-sim {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      background: var(--superficie-midia);
      border: 1px solid var(--borda-padrao);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 11px;
      font-weight: 700;
    }

    .comentario-item {
      padding: 8px 0;
      border-bottom: 1px solid var(--acao-secundaria);
      display: flex;
      gap: 8px;
      font-size: 12px;
      line-height: 1.4;
    }

    .comentario-conteudo {
      flex: 1;
      display: flex;
      flex-direction: column;
      gap: 2px;
    }

    .comentario-meta {
      display: flex;
      justify-content: space-between;
      color: var(--texto-secundario);
      font-size: 11px;
    }

    /* FOLHA DE CONFIGURAÇÃO / BOTTOM SHEET */
    .bottom-sheet-lofi {
      position: absolute;
      bottom: 0; left: 0; right: 0;
      background: var(--superficie-base);
      border-top: 2px solid var(--borda-foco);
      border-radius: 16px 16px 0 0;
      padding: 16px;
      display: flex;
      flex-direction: column;
      gap: 10px;
      z-index: 50;
      box-shadow: 0 -8px 24px rgba(0,0,0,0.25);
    }

    .menu-item-acao {
      padding: 11px;
      border: 1px solid var(--borda-padrao);
      border-radius: 6px;
      background: var(--superficie-elevada);
      font-size: 13px;
      font-weight: 600;
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .menu-item-acao:hover {
      background: var(--acao-secundaria);
    }

    /* MODAL PADRÃO */
    .modal-sobreposto {
      position: absolute;
      top: 0; left: 0; right: 0; bottom: 0;
      background: rgba(0,0,0,0.65);
      display: flex;
      align-items: center;
